\set ON_ERROR_STOP on
-- Separate database: explicit fixture-only EXECUTE grants, not customer DML.
GRANT EXECUTE ON FUNCTION public.admin_decide_review(uuid,boolean,text),public.admin_decide_claim(uuid,boolean,text) TO authenticated;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','',false);
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000002',true,NULL)$q$,'P0001','Not authorized');
SELECT public.qa_expect($q$SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000002',true,NULL)$q$,'P0001','Not authorized');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000002',true,NULL)$q$,'P0001','Not authorized');
SELECT public.qa_expect($q$SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000002',true,NULL)$q$,'P0001','Not authorized');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',false);
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000003',true,NULL)$q$,'P0001','Guide owners cannot moderate their own guide');
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000003',false,NULL)$q$,'P0001','Guide owners cannot moderate their own guide');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
SELECT public.qa_assert(current_user='authenticated' AND NOT (SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user),'moderator executes as non-superuser application role');
SELECT public.qa_expect($q$INSERT INTO public.guide_claims(guide_id,claimant_id) VALUES ('10000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000004')$q$,'42501',NULL);
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000004',true,NULL)$q$,'P0001','Cannot approve your own submission');
SELECT public.qa_expect($q$SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000003',true,NULL)$q$,'P0001','Cannot approve your own submission');
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000002',NULL,NULL)$q$,'P0001','Decision required');
SELECT public.qa_expect($q$SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000002',NULL,NULL)$q$,'P0001','Decision required');
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000001',true,NULL)$q$,'P0001','Only pending reviews can be decided');
SELECT public.qa_expect($q$SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000001',true,NULL)$q$,'P0001','Only pending claims can be decided');
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000099',true,NULL)$q$,'P0001','Not found');
RESET ROLE;
SELECT public.qa_assert((SELECT count(*)=3 FROM public.reviews WHERE status='pending' AND published_at IS NULL) AND (SELECT count(*)=2 FROM public.guide_claims WHERE status='pending') AND (SELECT count(*)=0 FROM public.moderation_audit) AND (SELECT review_count=1 AND average_quality=4 FROM public.guides WHERE id='10000000-0000-0000-0000-000000000001') AND (SELECT review_count=0 FROM public.guides WHERE id='10000000-0000-0000-0000-000000000002'),'all denied operations preserve every target status, aggregate and audit');
CREATE FUNCTION public.qa_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'QA injected audit failure'; END$$;
CREATE TRIGGER qa_audit_failure BEFORE INSERT ON public.moderation_audit FOR EACH ROW EXECUTE FUNCTION public.qa_audit_failure();
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
SELECT public.qa_expect($q$SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000002',true,NULL)$q$,'P0001','QA injected audit failure');
SELECT public.qa_expect($q$SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000002',true,NULL)$q$,'P0001','QA injected audit failure');
RESET ROLE;
DROP TRIGGER qa_audit_failure ON public.moderation_audit;
SELECT public.qa_assert((SELECT status='pending' AND published_at IS NULL FROM public.reviews WHERE id='30000000-0000-0000-0000-000000000002') AND (SELECT status='pending' FROM public.guide_claims WHERE id='20000000-0000-0000-0000-000000000002') AND (SELECT review_count=0 FROM public.guides WHERE id='10000000-0000-0000-0000-000000000002') AND (SELECT count(*)=0 FROM public.moderation_audit),'audit errors roll back review, claim and aggregate');
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
SELECT public.admin_decide_review('30000000-0000-0000-0000-000000000002',true,'independent');
SELECT public.admin_decide_claim('20000000-0000-0000-0000-000000000002',true,'independent');
RESET ROLE;
SELECT public.qa_assert((SELECT review_count=1 AND average_quality=3 FROM public.guides WHERE id='10000000-0000-0000-0000-000000000002') AND (SELECT status='approved' FROM public.guide_claims WHERE id='20000000-0000-0000-0000-000000000002') AND (SELECT count(*)=2 FROM public.moderation_audit WHERE actor_id='00000000-0000-0000-0000-000000000004'),'independent admin successfully moderates and writes two audit rows');
